{
  "findings": [
    {
      "what": "Toast lines use a noun phrase and colon instead of the required 해요체 sentence form for toasts",
      "quote": "toast.bulkSave.success = 저장 완료: {count} · 공간 {space}",
      "rule": "Toasts must be written in 해요체 (body/toast register); single-line notices must not use a colon and should be a sentence, not a bare noun phrase",
      "cite": [
        "vinc.spec.ui-copy-ko §1 1. Register",
        "vinc.spec.ui-copy-ko §2 2. Punctuation"
      ]
    },
    {
      "what": "The numeric variable {count} lacks a Korean counter noun or moved position so a particle does not end up directly after the variable",
      "quote": "{count}",
      "rule": "No particle directly after a variable; put a counter noun after it (문서 {n}개, {n}건) or move the variable so no particle follows",
      "cite": [
        "vinc.spec.ui-copy-ko §5 5. Template variables"
      ]
    },
    {
      "what": "Use of a colon (:) after 저장 완료 is disallowed in single-line toasts",
      "quote": \"저장 완료: {count} · 공간 {space}\",
      "rule": "No colon at the end of a sentence to announce a list; single-line notices/toasts should avoid terminal punctuation like a colon",
      "cite": [
        "vinc.spec.ui-copy-ko §2 2. Punctuation"
      ]
    }
  ],
  "verdict": "RETURN"
}
